      "where": "at the front end of the body, turned about three-quarters toward the viewer"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with light tawny fur on the rims and dark blackish patches on the backs",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "mane",
      "looks_like": "a ruff of longer shaggy fur, tawny on the sides and cream-white on the front, slightly tousled",
