    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in tawny fur with darker horizontal striping most distinct on the hind legs and lower front legs",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body in a standing pose"
    },
    {
      "part": "feet",
      "looks_like": "four large rounded paws with thick toes and short claws, the front paws viewed from the front and the hind paws in side view, with pale fur on the lower surfaces",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short and relatively thin, striped with alternating light and dark bands and ending in a dark blackish tuft",
      "where": "at the rear of the body, protruding from the rump and angled slightly down and out"
    },
    {
      "part": "markings",
      "looks_like": "faint vertical and horizontal dark brown to blackish stripes over the back, sides, and legs, denser and darker on the lower hind legs, with a pale cream-white underside, chest and chin",
